namespace Inventory;

/// <summary>Builds a replenishment plan across a set of stock items.</summary>
public sealed class ReplenishmentPlanner
{
    public IReadOnlyList<string> BuildPlan(IEnumerable<StockItem> items, ISupplier supplier, int season)
    {
        var plan = new List<string>();

        foreach (var item in items)
        {
            if (!ShouldReplenish(item))
                continue;

            int orderQuantity = CalculateOrderQuantity(item, season);
            if (orderQuantity <= 0 || string.IsNullOrEmpty(item.Sku))
                continue;

            plan.Add(PlaceOrder(supplier, item.Sku, orderQuantity));
        }

        return plan;
    }

    private static bool ShouldReplenish(StockItem item)
    {
        if (item.OnHand < 0)
            return false;

        int available = item.OnHand - item.Reserved;
        return available <= item.ReorderPoint;
    }

    private static int CalculateOrderQuantity(StockItem item, int season)
    {
        int available = item.OnHand - item.Reserved;
        int deficit = item.ReorderPoint - available;
        int orderQuantity = CalculateBaseOrderQuantity(deficit);

        if (season == 4 && orderQuantity > 0)
            return (int)(orderQuantity * 1.5);

        if (season == 1)
            return orderQuantity / 2;

        return orderQuantity;
    }

    private static int CalculateBaseOrderQuantity(int deficit)
    {
        if (deficit <= 0)
            return 0;
        if (deficit < 10)
            return 10;
        if (deficit < 100)
            return deficit;

        return deficit + 50;
    }

    private static string PlaceOrder(ISupplier supplier, string sku, int orderQuantity)
    {
        bool placed = supplier.PlaceOrder(sku, orderQuantity);
        if (!placed)
            return $"{sku}:FAILED";

        return orderQuantity > 200
            ? $"{sku}:LARGE:{orderQuantity}"
            : $"{sku}:{orderQuantity}";
    }
}
